head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.TR_JOB = 'I';
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.vBzTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const parentWin = $c.frame.path("../");
        scwin.vBzTpCd = parentWin.fn_getbzTpCd();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        popUpCalendar2(edt_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05906.img_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name grd_List_onheadcheckclick
 * @description grd_List onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_onheadcheckclick = function(col, colid, bCheck) {
    try {
        $c.elw.fn_setCheckBox(grd_List, dts_List, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05906.grd_List_onheadcheckclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt.setValue("총 " + dts_List.getRowCount() + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05906.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await $c.win.closePopup();
        scwin.parentRefresh(); // 목록 다시 조회
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05906.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&LIST_BZ_TP_CD=" + scwin.vBzTpCd;
    url += "&SCREN_ID=" + "ULDSTF05906.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let k = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "CHECK") === "T") {
            k++;
        }
    }
    if (k === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return;
    }
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "CHECK") === "T") // 이것이 여태 빠져 있었네. ^^;;;   jackal_ko_10.06.15

        {
            dts_List.setCellData(i, "LIST_DD", edt_LIST_DD.getValue());
            dts_List.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_13);
        }
    }
    dts_List.setBroadcast(true, true);
    // dts_Isu.UserStatus(1) = TB_JOB_UPDATE;

    // alert('[dtsObj]'+dtsObj.text);
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/ElwListedReceive.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};

/**
 * @method
 * @name grd_List_CanColumnPosChange
 * @description grd List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
